/**
 * Default (production-shaped) dependency implementations for gemini_ocr.ts.
 * Split out so gemini_ocr.ts stays focused on orchestration; also makes it
 * obvious at a glance which pieces are subprocess/filesystem/network I/O
 * (this file) vs pure orchestration logic (gemini_ocr.ts) vs pure math
 * (gemini_ocr_batching.ts).
 */
import { spawn } from 'node:child_process';
import { readFile, rm, stat } from 'node:fs/promises';
import * as path from 'node:path';
import { fileURLToPath } from 'node:url';
import { ocrFailed } from '../errors.js';
import { generate as geminiGenerate } from '../gemini-client.js';
import { OCR_MODEL, OCR_THINKING_BUDGET, buildOcrParts } from '../gemini-client-ocr-helpers.js';
import {
  GEMINI_OCR_RESPONSE_SCHEMA,
  type DetectResult,
  type GeminiOcrDeps,
  type OcrGenerateArgs,
  type OcrGenerateResult,
  type RasterizeResult,
} from './gemini_ocr_types.js';

// NOTE: this file lives at src/tools/gemini_ocr_deps.ts pre-bundle (two
// levels below the gemini-server root), but esbuild bundles everything into
// a single dist/index.js — so at runtime `import.meta.url` points at
// dist/index.js, only ONE level below the gemini-server root (dist/), not
// two. `scriptsDir` must walk up accordingly: dist/../scripts, matching
// bundle.ts's own pluginRoot() convention of resolving relative to the
// compiled entry point rather than this module's pre-bundle location.
// (INTEGRATION-PLAN.md §1 flagged this as the one path-math risk worth a
// post-build smoke test — verified via a real gemini_ocr call, see the
// integration report.)
const scriptsDir = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', 'scripts');

/** Runs `python3 <script> <args...>` and parses its single-line JSON stdout. */
async function runPythonJson(scriptName: string, args: string[]): Promise<Record<string, unknown>> {
  const scriptPath = path.join(scriptsDir, scriptName);
  return new Promise((resolve, reject) => {
    const proc = spawn('python3', [scriptPath, ...args]);
    let stdout = '';
    let stderr = '';
    proc.stdout.on('data', (d: Buffer) => (stdout += d.toString()));
    proc.stderr.on('data', (d: Buffer) => (stderr += d.toString()));
    proc.on('error', (err) => reject(err));
    proc.on('close', (code) => {
      let parsed: unknown;
      try {
        parsed = JSON.parse(stdout.trim());
      } catch {
        reject(
          ocrFailed(
            `${scriptName} produced no valid JSON output (exit code ${code}). stderr: ${stderr.slice(0, 500)}`,
          ) as unknown as Error,
        );
        return;
      }
      if (parsed && typeof parsed === 'object' && 'error' in parsed) {
        reject(ocrFailed((parsed as { error: string }).error) as unknown as Error);
        return;
      }
      if (code !== 0) {
        reject(
          ocrFailed(`${scriptName} exited with code ${code}: ${stderr.slice(0, 500)}`) as unknown as Error,
        );
        return;
      }
      resolve(parsed as Record<string, unknown>);
    });
  });
}

/**
 * Default Gemini call — wired to the real gemini-client.ts's extended
 * `generate()` (accepts a `parts` array for vision calls, plus `topK`,
 * `thinkingConfig`, `generationConfig.mediaResolution`, `responseSchema`).
 * Pinned to gemini-2.5-flash / thinkingBudget:0 / temperature:0 / topK:1 per
 * C6 (see gemini-client-ocr-helpers.ts's OCR_MODEL doc for why). Only ever
 * invoked for pages that actually need vision OCR (born-digital pages never
 * reach here — see gemini_ocr.ts). If no Gemini API key is configured,
 * `generate()`'s own `getClient()` throws the standard `no_credentials`
 * StructuredError at this point, deferred exactly as far as it needs to be
 * (see index.ts's `wrapDeferredCredentials`).
 */
async function defaultGenerate(args: OcrGenerateArgs): Promise<OcrGenerateResult> {
  const imageParts = args.images.map((img) => ({
    inlineData: { mimeType: img.mimeType, data: img.data },
  }));
  const parts = buildOcrParts(imageParts, args.promptText);
  const result = await geminiGenerate({
    system: '',
    user: args.promptText,
    parts,
    model: OCR_MODEL,
    thinking_budget: OCR_THINKING_BUDGET,
    temperature: 0,
    topK: 1,
    thinkingConfig: { thinkingBudget: OCR_THINKING_BUDGET },
    generationConfig: { mediaResolution: args.mediaResolution },
    response_mime_type: 'application/json',
    responseSchema: GEMINI_OCR_RESPONSE_SCHEMA,
  });
  return { text: result.text, finishReason: result.finishReason };
}

export function defaultDeps(): GeminiOcrDeps {
  return {
    generate: defaultGenerate,
    runDetectTextLayer: async (documentPath, pagesSpec) => {
      const args = pagesSpec ? [documentPath, '--pages', pagesSpec] : [documentPath];
      return (await runPythonJson('detect_text_layer.py', args)) as unknown as DetectResult;
    },
    runRasterizePages: async (documentPath, pageNumbers) => {
      const spec = pageNumbers.join(',');
      return (await runPythonJson('rasterize_pages.py', [
        documentPath,
        '--pages',
        spec,
      ])) as unknown as RasterizeResult;
    },
    readFileBase64: async (filePath) => {
      const buf = await readFile(filePath);
      return { data: buf.toString('base64'), rawBytes: buf.length };
    },
    cleanupDir: async (dir) => {
      await rm(dir, { recursive: true, force: true });
    },
    fileExists: async (filePath) => {
      try {
        await stat(filePath);
        return true;
      } catch {
        return false;
      }
    },
  };
}
